58	/* --------------------------------------------------------
59	 * VM initialization
60	 * -------------------------------------------------------- */
61	
62	VM_INIT: PROC;
63	    DCL I INT;
64	
65	    /* Zero all memory */
66	    DO I = 0 TO 7703;
67	        MEM(I) = 0;
68	    END;
69	
70	    /* Set initial register values */
71	    CALL REG_SET(REG_PC, CODE_BASE);
72	    CALL REG_SET(REG_HP, HEAP_BASE);
73	    CALL REG_SET(REG_TR, TRAIL_BASE);
74	    CALL REG_SET(REG_EP, ENV_BASE);
75	    CALL REG_SET(REG_BP, CP_BASE);
76	    CALL REG_SET(REG_MODE, 0);
77	END;
78	
79	/* --------------------------------------------------------
80	 * Instruction decode
81	 *
82	 * Uses ?INST_DECODE macro from opcodes.msw. Generates
83	 * COR24 srl/and instructions -- no software divide.
84	 * Results stored in globals G_OP, G_OP1, G_OP2.
85	 * -------------------------------------------------------- */
86	
87	/* --------------------------------------------------------
88	 * Trace output
89	 *
90	 * Prints PC and opcode before each instruction.
91	 * -------------------------------------------------------- */
92	
93	DCL T_MSG(4) CHAR INIT('PC=');
94	DCL T_SEP(5) CHAR INIT(' op=');
95	
96	PRINT_INT: PROC(N INT);
97	    DCL D INT;
98	    DCL R INT;
99	    DCL BUF(8) CHAR;
100	    DCL POS INT;
101	    DCL NEG INT;
102	
103	    IF (N = 0) THEN DO;
104	        CALL UART_PUTCHAR(48);
105	        RETURN;
106	    END;
107	
108	    NEG = 0;
109	    IF (N < 0) THEN DO;
110	        NEG = 1;
111	        N = 0 - N;
112	    END;
113	
114	    POS = 7;
115	    BUF(POS) = 0;
116	    DO WHILE (N > 0);
117	        POS = POS - 1;
118	        D = N / 10;
119	        R = N - D * 10;
120	        BUF(POS) = R + 48;
121	        N = D;
122	    END;
123	
124	    IF (NEG = 1) THEN DO;
125	        POS = POS - 1;
126	        BUF(POS) = 45;
127	    END;
128	
129	    CALL UART_PUTS(ADDR(BUF) + POS);
130	END;
131	
132	VM_TRACE: PROC(PC INT, OP INT);
133	    CALL UART_PUTS(ADDR(T_MSG));
134	    CALL PRINT_INT(PC);
135	    CALL UART_PUTS(ADDR(T_SEP));
136	    CALL PRINT_INT(OP);
137	    CALL UART_PUTCHAR(10);
138	END;
