    TAG = CELL_TAG(CELL);
    IF (TAG != TAG_REF) THEN
        RETURN(0);
    PAY = CELL_PAY(CELL);
    IF (MEM(PAY) = CELL) THEN
        RETURN(1);
    RETURN(0);
END;

