/* Save a full choice-point frame at the current BP.
 * ALT is the code address of the next alternative clause.
 * Advances BP by CP_FRAME_SIZE. */
CP_PUSH: PROC(ALT INT);
    DCL BP INT;
    BP = REG_GET(REG_BP);
    IF (BP + CP_FRAME_SIZE > CP_BASE + CP_STKSZ) THEN DO;
        CALL UART_PUTS(ADDR(M_CPOV));
        G_RUNNING = 0;
        RETURN;
    END;
    CALL CP_WRITE(BP, CPF_PREV_BP,  BP);
    CALL CP_WRITE(BP, CPF_SAVED_CP, REG_GET(REG_CP));
    CALL CP_WRITE(BP, CPF_SAVED_EP, REG_GET(REG_EP));
    CALL CP_WRITE(BP, CPF_SAVED_HP, REG_GET(REG_HP));
    CALL CP_WRITE(BP, CPF_SAVED_TR, REG_GET(REG_TR));
    CALL CP_WRITE(BP, CPF_NEXT_ALT, ALT);
    CALL CP_WRITE(BP, CPF_SAVED_A0, REG_GET(REG_A0));
    CALL CP_WRITE(BP, CPF_SAVED_A1, REG_GET(REG_A1));
    CALL CP_WRITE(BP, CPF_SAVED_A2, REG_GET(REG_A2));
    CALL CP_WRITE(BP, CPF_SAVED_A3, REG_GET(REG_A3));
    CALL CP_WRITE(BP, CPF_SAVED_A4, REG_GET(REG_A4));
    CALL CP_WRITE(BP, CPF_SAVED_A5, REG_GET(REG_A5));
    CALL CP_WRITE(BP, CPF_SAVED_A6, REG_GET(REG_A6));
    CALL CP_WRITE(BP, CPF_SAVED_A7, REG_GET(REG_A7));
    CALL REG_SET(REG_BP, BP + CP_FRAME_SIZE);
END;

/* Restore state from the most recent choice-point frame.
 * Unwinds trail, resets HP, restores A0-A7 and CP/EP.
 * Pops the frame by setting BP = prev_BP.
 * Returns the next_alt address so the caller can jump there. */
CP_POP: PROC RETURNS(INT);
    DCL FB INT;
    DCL ALT INT;
    DCL SAVED_TR INT;
    DCL SAVED_HP INT;
    FB = REG_GET(REG_BP) - CP_FRAME_SIZE;

    /* Unwind trail and reset heap first */
    SAVED_TR = CP_READ(FB, CPF_SAVED_TR);
    SAVED_HP = CP_READ(FB, CPF_SAVED_HP);
    CALL TRAIL_UNWIND(SAVED_TR);
    CALL REG_SET(REG_HP, SAVED_HP);

    /* Restore registers */
    CALL REG_SET(REG_CP, CP_READ(FB, CPF_SAVED_CP));
    CALL REG_SET(REG_EP, CP_READ(FB, CPF_SAVED_EP));
    CALL REG_SET(REG_A0, CP_READ(FB, CPF_SAVED_A0));
    CALL REG_SET(REG_A1, CP_READ(FB, CPF_SAVED_A1));
    CALL REG_SET(REG_A2, CP_READ(FB, CPF_SAVED_A2));
    CALL REG_SET(REG_A3, CP_READ(FB, CPF_SAVED_A3));
    CALL REG_SET(REG_A4, CP_READ(FB, CPF_SAVED_A4));
    CALL REG_SET(REG_A5, CP_READ(FB, CPF_SAVED_A5));
    CALL REG_SET(REG_A6, CP_READ(FB, CPF_SAVED_A6));
    CALL REG_SET(REG_A7, CP_READ(FB, CPF_SAVED_A7));

    /* Get alt and pop */
    ALT = CP_READ(FB, CPF_NEXT_ALT);
    CALL REG_SET(REG_BP, CP_READ(FB, CPF_PREV_BP));
    RETURN(ALT);
END;

