/* Store a string into atom table slot ID.
 * STR_ADDR is the address of a null-terminated CHAR array.
 * Copies up to ATOM_SLOT_SIZE-1 chars, null-terminates. */
ATOM_STORE: PROC(ID INT, C0 INT, C1 INT, C2 INT, C3 INT,
                  C4 INT, C5 INT, C6 INT);
    DCL BASE INT;
    BASE = ATOM_BASE + ID * ATOM_SLOT_SIZE;
    MEM(BASE)     = C0;
    MEM(BASE + 1) = C1;
    MEM(BASE + 2) = C2;
    MEM(BASE + 3) = C3;
    MEM(BASE + 4) = C4;
    MEM(BASE + 5) = C5;
    MEM(BASE + 6) = C6;
    MEM(BASE + 7) = 0;
END;

/* Initialize the atom table with known atoms. */
ATOM_INIT: PROC;
    /* 0: []       */  CALL ATOM_STORE(0, 91, 93, 0, 0, 0, 0, 0);
    /* 1: bob      */  CALL ATOM_STORE(1, 98, 111, 98, 0, 0, 0, 0);
    /* 2: ann      */  CALL ATOM_STORE(2, 97, 110, 110, 0, 0, 0, 0);
    /* 3: joe      */  CALL ATOM_STORE(3, 106, 111, 101, 0, 0, 0, 0);
    /* 4: liz      */  CALL ATOM_STORE(4, 108, 105, 122, 0, 0, 0, 0);
    /* 5: parent   */  CALL ATOM_STORE(5, 112, 97, 114, 101, 110, 116, 0);
    /* 6: ancestor */  CALL ATOM_STORE(6, 97, 110, 99, 101, 115, 116, 111);
    /* Note: "ancestor" is 8 chars, truncated to 7 + null.
     * PLSW-ISSUE: ATOM_SLOT_SIZE of 8 is tight for longer names.
