        WHEN (WTAG = TAG_REF) DO;
            CALL UART_PUTCHAR(95);  /* _ */
            CALL UART_PUTCHAR(86);  /* V */
            CALL PRINT_INT(WPAY);
        END;
        OTHERWISE DO;
            CALL PRINT_INT(WVAL);
        END;
    END;
    CALL REG_SET(REG_PC, PC + 1);
END;

