612	    MEM(0)  = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
613	    MEM(1)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
614	    MEM(2)  = OP_PUT_CONST * OP_MULT + 1 * OP1_MULT;  /* PUT_CONST A1 */
615	    MEM(3)  = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
616	    MEM(4)  = OP_CALL * OP_MULT;                       /* CALL */
617	    MEM(5)  = 8;                                        /* target: addr 8 */
618	    MEM(6)  = OP_HALT * OP_MULT;                       /* HALT */
619	
620	    /* Clause: parent(bob, ann). at addr 8 */
621	    MEM(8)  = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
622	    MEM(9)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
623	    MEM(10) = OP_GET_CONST * OP_MULT + 1 * OP1_MULT;  /* GET_CONST A1 */
624	    MEM(11) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
625	    MEM(12) = OP_PROCEED * OP_MULT;                    /* PROCEED */
626	END;
