628	/* --------------------------------------------------------
629	 * Negative test: query parent(bob, joe) against
630	 * clause parent(bob, ann). Should FAIL at GET_CONST A1.
631	 *
632	 * Atoms: 1=bob, 2=ann, 3=joe
633	 * -------------------------------------------------------- */
634	
635	LOAD_FACT_FAIL: PROC;
636	    /* Query: ?- parent(bob, joe). */
637	    MEM(0)  = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
638	    MEM(1)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
639	    MEM(2)  = OP_PUT_CONST * OP_MULT + 1 * OP1_MULT;  /* PUT_CONST A1 */
640	    MEM(3)  = TAG_ATOM * TAG_MULT + 3;                 /* atom(joe) <-- different */
641	    MEM(4)  = OP_CALL * OP_MULT;                       /* CALL */
642	    MEM(5)  = 8;                                        /* target: addr 8 */
643	    MEM(6)  = OP_HALT * OP_MULT;                       /* HALT */
644	
645	    /* Clause: parent(bob, ann). at addr 8 */
646	    MEM(8)  = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
647	    MEM(9)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
648	    MEM(10) = OP_GET_CONST * OP_MULT + 1 * OP1_MULT;  /* GET_CONST A1 */
649	    MEM(11) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
650	    MEM(12) = OP_PROCEED * OP_MULT;                    /* PROCEED */
651	END;
