929	     * Query parent(bob, X) against clause parent(bob, ann).
930	     * GET_CONST A0 matches bob directly.
931	     * GET_CONST A1 finds unbound REF, binds to atom(ann).
932	     * After PROCEED, deref A1 should give atom(ann) = 4194306.
933	     */
934	    CALL UART_PUTS(ADDR(M_TEST5));
