988	    CALL UART_PUTS(ADDR(M_UB));
989	    CALL PRINT_INT(IS_UNBOUND(V2_REF));
990	    CALL UART_PUTCHAR(10);
991	
992	    /* Test 7: TRY/TRUST -- choice point creation
993	     * Query pred(bob) against pred(bob) / pred(ann).
994	     * TRY pushes choice point, clause1 matches, PROCEED.
995	     * Show BP changed (choice point exists).
996	     */
997	    CALL UART_PUTS(ADDR(M_TEST7));
998	    CALL UART_PUTCHAR(10);
999	    CALL VM_INIT;
1000	    CALL LOAD_TRY_TEST;
1001	    CALL UART_PUTS(ADDR(M_BP));
1002	    CALL PRINT_INT(REG_GET(REG_BP));
1003	    CALL VM_RUN;
1004	    CALL UART_PUTS(ADDR(M_BP));
1005	    CALL PRINT_INT(REG_GET(REG_BP));
1006	    CALL UART_PUTS(ADDR(M_A0));
1007	    CALL PRINT_INT(REG_GET(REG_A0));
1008	    CALL UART_PUTCHAR(10);
1009	
1010	    /* Test 8: Backtracking via FAIL
1011	     * Query pred(ann) against pred(bob) / pred(ann).
1012	     * Clause1 fails (bob != ann), backtracks to clause2.
1013	     * TRUST pops choice point, GET_CONST matches ann, PROCEED.
1014	     *
1015	     * Trace should show:
1016	     *   TRY -> GET_CONST A0 bob (fail, backtrack) ->
1017	     *   TRUST -> GET_CONST A0 ann (match) -> PROCEED -> HALT
1018	     */
1019	    CALL UART_PUTS(ADDR(M_TEST8));
1020	    CALL UART_PUTCHAR(10);
1021	    CALL VM_INIT;
1022	    CALL LOAD_BACKTRACK_TEST;
1023	    CALL VM_RUN;
1024	    CALL UART_PUTS(ADDR(M_A0));
1025	    CALL PRINT_INT(REG_GET(REG_A0));
1026	    CALL UART_PUTCHAR(10);
1027	
1028	    /* Test 9: two_facts -- the saga milestone
1029	     * parent(bob, ann). parent(bob, joe).
1030	     * ?- parent(bob, X), write(X), nl, fail.
1031	     *
1032	     * Expected output:
1033	     *   4194306   (ann as tagged int)
1034	     *   4194307   (joe as tagged int)
1035	     *   FAIL      (no more choice points)
1036	     */
1037	    CALL UART_PUTS(ADDR(M_TEST9));
1038	    CALL UART_PUTCHAR(10);
1039	    CALL VM_INIT;
1040	    CALL LOAD_TWO_FACTS;
1041	    CALL VM_RUN;
